#!/usr/bin/env node
/**
 * Bundle help/knowledge/** into tgcloud/lib/knowledge.js.
 *
 * The serverless platform has no filesystem, so the knowledge base ships as
 * a generated JS module. This is a faithful port of the Python chunking in
 * help/helpbot/kb.py (_split_sections + _pack + _h1), so the JS index and
 * the Python BM25 index see identical chunks in identical order.
 *
 * Usage: node tools/build_knowledge.mjs   (or: npm run kb)
 * Re-run after editing anything under help/knowledge/, then commit the
 * generated file so `npx tgcloud push` deploys it.
 */
import { readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('..', import.meta.url));
const KNOWLEDGE_DIR = join(ROOT, 'help', 'knowledge');
const OUT = join(ROOT, 'tgcloud', 'lib', 'knowledge.js');

/** Longest single chunk (matches kb.py MAX_CHUNK_CHARS). */
const MAX_CHUNK_CHARS = 1100;
const HEADING_RE = /^(#{1,4})\s+(.*?)\s*$/;

/** Recursively list *.md files under dir, sorted like Python's sorted(rglob). */
function listMd(dir) {
  const out = [];
  const walk = (d) => {
    for (const name of readdirSync(d)) {
      const p = join(d, name);
      if (statSync(p).isDirectory()) walk(p);
      else if (name.endsWith('.md')) out.push(relative(KNOWLEDGE_DIR, p).split(sep).join('/'));
    }
  };
  walk(dir);
  // Python compares Windows PurePaths case-insensitively; all knowledge file
  // names are lowercase/digits, so a plain string compare orders identically.
  return out.sort();
}

/** First `# heading` in the file, or '' (port of kb.py _h1). */
function h1(text) {
  for (const line of text.split('\n')) {
    const m = line.match(HEADING_RE);
    if (m && m[1].length === 1) return m[2].trim();
  }
  return '';
}

/** Split markdown into [headingTrail, bodyLines] sections (port of _split_sections). */
function splitSections(lines) {
  const sections = [];
  let trail = [];
  let body = [];
  const flush = () => {
    if (body.some((ln) => ln.trim())) sections.push([trail.filter(Boolean).join(' > '), body]);
    body = [];
  };
  for (const line of lines) {
    const m = line.match(HEADING_RE);
    if (m) {
      const level = m[1].length;
      flush();
      trail = trail.slice(0, level - 1);
      while (trail.length < level) trail.push('');
      trail[level - 1] = m[2].trim();
      continue;
    }
    body.push(line);
  }
  flush();
  return sections;
}

/** Pack body lines into ~1100-char chunks on line boundaries (port of _pack). */
function pack(body, heading) {
  const chunks = [];
  let current = [];
  let size = heading.length;
  for (const line of body) {
    if (size + line.length + 1 > MAX_CHUNK_CHARS && current.length) {
      chunks.push(current.join('\n').trim());
      current = [];
      size = heading.length;
    }
    current.push(line);
    size += line.length + 1;
  }
  if (current.length) chunks.push(current.join('\n').trim());
  return chunks.filter(Boolean);
}

const files = [];
const chunks = [];
for (const source of listMd(KNOWLEDGE_DIR)) {
  const text = readFileSync(join(KNOWLEDGE_DIR, source), 'utf8');
  files.push({ stem: source.split('/').pop().replace(/\.md$/, ''), source, title: h1(text), text });
  for (const [heading, body] of splitSections(text.split('\n'))) {
    for (const piece of pack(body, heading)) chunks.push({ source, heading, text: piece });
  }
}

const emit = (name, rows) =>
  `export const ${name} = [\n${rows.map((r) => JSON.stringify(r)).join(',\n')}\n];\n`;

const banner = `// AUTO-GENERATED by tools/build_knowledge.mjs — do not edit by hand.\n` +
  `// Source: help/knowledge/**/*.md (${files.length} files, ${chunks.length} chunks). \`npm run kb\` to rebuild.\n`;

writeFileSync(OUT, banner + emit('FILES', files) + emit('CHUNKS', chunks), 'utf8');

const bytes = statSync(OUT).size;
console.log(`knowledge.js: ${files.length} files, ${chunks.length} chunks, ${(bytes / 1024).toFixed(1)} KB -> tgcloud/lib/knowledge.js`);
